function piFoldState(n) {
  try { return localStorage.getItem('pi_fold_' + n) === '1'; } catch (e) { return false; }
}
window.piApplyFolds = function () {
  for (var n = 2; n <= 5; n++) {
    var p = document.getElementById('pi-panel-' + n);
    if (!p) continue;
    var collapsed = piFoldState(n);
    var kids = p.children;
    for (var i = 1; i < kids.length; i++) {
      var el = kids[i];
      if (el.getAttribute('data-pi-disp') == null) el.setAttribute('data-pi-disp', el.style.display || '');
      el.style.display = collapsed ? 'none' : (el.getAttribute('data-pi-disp') || '');
    }
    var c = document.getElementById('pi-fold-c' + n);
    if (c) c.textContent = collapsed ? '▸' : '▾';
  }
};
window.piToggleFold = function (n) {
